using System.Data; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class BlogPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetPosts() { return new { success = true, data = DbHelper.ToDictionaryList(DbHelper.ExecuteDataTable(@"SELECT TOP 12 b.PostID, b.Title, b.Summary, bc.CategoryName, b.LanguageCode FROM BlogPosts b INNER JOIN BlogCategories bc ON bc.CategoryID = b.CategoryID WHERE b.IsPublished = 1 ORDER BY b.IsFeatured DESC, b.PublishedDate DESC", CommandType.Text)) }; } } }
